			    if(bitAnd(common_flags, 32)= 32, 'Download', ''),
			    if(bitAnd(common_flags, 64)= 64, 'Interactive', ''),
			    if(bitAnd(common_flags, 128)= 128, 'Inbound', ''),
			    if(bitAnd(common_flags, 256)= 256, 'Outbound', ''),
			    if(bitAnd(common_flags, 512)= 512, 'Pseudo Unidirectional', ''),
			    if(bitAnd(common_flags, 1024)= 1024, 'Streaming', ''),
			    if(bitAnd(common_flags, 2048)= 2048, 'Unidirectional', ''),
			    if(bitAnd(common_flags, 4096)= 4096, 'Random looking', ''), 
			    if(bitAnd(common_flags, 8192)= 8192, 'C2S', ''), 
			    if(bitAnd(common_flags, 16384)= 16384, 'S2C', ''), 
			    if(common_flags=0, 'N/A', '')
			    )) as flag , bytes, packets, sessions
			    from (

		select
				common_flags,
				count(*) as sessions,
				sum(common_c2s_byte_num + common_s2c_byte_num) as bytes,
				sum(common_c2s_pkt_num + common_s2c_pkt_num) as packets
			from
				session_record as sr
